{"implementation": "def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")

    if "threshold" not in case:
        raise ValueError("Missing required field 'threshold'")
    if "calls" not in case:
        raise ValueError("Missing required field 'calls'")

    threshold = case["threshold"]
    calls = case["calls"]

    if not isinstance(calls, list):
        raise ValueError("'calls' must be a list")

    required_fields = ("call_id", "loss_without_call", "loss_with_call", "prediction_tokens", "parseable")

    diagnostics = []
    accepted_call_ids = []

    for call in calls:
        for field in required_fields:
            if field not in call:
                raise ValueError(f"Missing required field '{field}' in call")

        call_id = call["call_id"]
        loss_without = call["loss_without_call"]
        loss_with = call["loss_with_call"]
        prediction_tokens = call["prediction_tokens"]
        parseable = call["parseable"]

        # Normalize by at least one prediction token (stronger counterfactual)
        tokens = max(int(prediction_tokens), 1)
        gain = loss_without - loss_with
        normalized_gain = gain / tokens

        # Inclusive threshold: accept if parseable AND normalized_gain >= threshold
        accepted = bool(parseable) and (normalized_gain >= threshold)

        diagnostics.append({
            "call_id": call_id,
            "normalized_gain": normalized_gain,
            "accepted": accepted
        })

        if accepted:
            accepted_call_ids.append(call_id)

    return {
        "accepted_call_ids": accepted_call_ids,
        "diagnostics": diagnostics
    }
